L = dict(title='Unit 4: Software Testing', points=[
 'Error is human mistake, fault or bug is the defect in code, failure is wrong behaviour when the program runs',
 'Verification asks are we building the product right, validation asks are we building the right product',
 'Levels of testing: unit, integration, system, acceptance. Integration can be big bang, top down with stubs, bottom up with drivers, or sandwich',
 'White box looks inside the code: statement, branch, condition and path coverage',
 'Cyclomatic complexity V of G = E minus N plus 2 = P plus 1 = number of regions. It equals the number of independent paths',
 'Basis path steps: draw flow graph, find V of G, list independent paths, write one test case per path',
 'BVA tests min, min plus, nominal, max minus, max. Single fault gives 4n plus 1, robust gives 6n plus 1, worst case gives 5 to the power n',
 'Equivalence class testing: one test from each valid and invalid class',
 'Decision table: conditions on top, actions below, every column is a rule and a test case',
 'Cause effect graph converts causes and effects to a decision table. State table testing checks every state and event pair',
 'Agile testing is continuous. TDD cycle is red, green, refactor'], scenes=[
 S('Namaste! Yeh hai Unit chaar, Software Testing. Analogy: Angry Birds mein green pigs hain bugs, aur testing hai slingshot jo unhe dhoondh kar girata hai. Pehle poora map dekh lo, isme sab kuch hai, chhote se chhota topic bhi. Error aur fault se shuru, phir verification validation, levels, white box, black box, aur end mein agile testing. Numericals bhi hain: cyclomatic complexity, boundary value, decision table.',
  'Pura Unit 4 ka map. Har box ek topic hai!',
  [['map', 'SOFTWARE TESTING', [('Basics', ['Error', 'Fault / bug', 'Failure', 'Verification vs Validation']), ('Levels', ['Unit', 'Integration: big bang, top down, bottom up, sandwich', 'System: stress, security, recovery', 'Acceptance: alpha, beta']), ('White Box', ['Static testing', 'Structural testing', 'Statement / branch / condition / path coverage', 'Flow graph']), ('Basis Path', ['Flow graph notation', 'V(G) = E - N + 2', 'Independent paths', 'Derive test cases']), ('Black Box', ['Boundary value analysis', 'Robust / worst case', 'Equivalence class']), ('Tables', ['Decision table', 'Cause effect graph', 'State table testing']), ('Agile Testing', ['Continuous testing', 'TDD: red green refactor', 'Test quadrants']), ('PYQ Hit List', ['V and V difference', 'Credit card discount test cases', 'Cyclomatic numerical', 'BVA numerical'])]]],
  [], 'Unit 4 Map', True, False),
 S('Pehla topic. Error, fault aur failure. Analogy: programmer ne galti ki, wo hai error. Galti code mein ek bug ban kar baith gayi, wo hai fault, yaani green pig chhup gaya. Jab program chala aur galat answer aaya, wo hai failure, pig bahar aa gaya. To chain hai: error se fault, fault se failure.',
  'Error (insaan ki galti) > Fault (code mein bug) > Failure (run pe galat output)',
  [['h', 'Error > Fault > Failure'], ['row', ['Error (human mistake)', 'Fault / Bug (in code)', 'Failure (wrong output)']], ['tbl', [['Term', 'Where', 'Example'], ['Error', 'Programmer mind', 'Typed + instead of -'], ['Fault', 'Source code', 'total = a + b (wrong)'], ['Failure', 'Running system', 'ATM shows wrong balance']]]],
  ['## Definitions', 'Error: mistake made by a developer', 'Fault (bug, defect): incorrect step in the code caused by an error', 'Failure: system behaves differently from expected when fault is executed', '! Error > Fault > Failure', '~ A fault may never cause a failure if that line never runs'], None, False, True),
 S('Ab verification versus validation, yeh PYQ hai. Verification matlab kya hum product sahi bana rahe hain. Ye documents, design aur code ka review hota hai, bina program chalaye. Validation matlab kya hum sahi product bana rahe hain, yaani customer ki zarurat poori ho rahi hai, isme program chalate hain. V model mein left side verification, right side validation. Sawaal poochta hai kya dono mein test case design aur strategies use hoti hain. Jawab: validation mein haan, verification mein review checklists aur inspection use hote hain.',
  'Verification: product SAHI bana? Validation: SAHI product bana?',
  [['tbl', [['Point', 'Verification', 'Validation'], ['Question', 'Built right?', 'Built the right thing?'], ['Type', 'Static (no run)', 'Dynamic (run code)'], ['Methods', 'Review, walkthrough, inspection', 'Unit, integration, system, UAT'], ['When', 'Early phases', 'After code ready'], ['Done by', 'QA team', 'Testers / users']]], ['graph', [('r', 'Requirements', 0.15, 0.1, 'box', 0), ('d', 'Design', 0.3, 0.42, 'box', 1), ('c', 'Coding', 0.5, 0.8, 'box', 2), ('u', 'Unit test', 0.7, 0.42, 'box', 3), ('a', 'Acceptance test', 0.85, 0.1, 'box', 4)], [('r', 'd'), ('d', 'c'), ('c', 'u'), ('u', 'a')], 150]],
  ['## Q: V vs V', '! Verification = are we building the product right', '! Validation = are we building the right product', '## Do both use test case design and strategies?', 'Validation: YES. Black box and white box test case design, plus unit, integration, system, acceptance strategies', 'Verification: NO execution. Uses reviews, inspections, walkthroughs, checklists', '~ V model: left arm verification, right arm validation'], None, False, False),
 S('Levels of testing. Pokemon evolution jaisa socho. Pehle Pichu, yaani unit testing, ek chhota module akela. Phir Pikachu, integration testing, modules ko jodkar. Phir Raichu, system testing, poora system. Aur end mein Mega form, acceptance testing, customer khud check karta hai. Har level ke baad agla level unlock hota hai.',
  'Unit > Integration > System > Acceptance (Pichu > Pikachu > Raichu > Mega)',
  [['h', 'Levels of testing'], ['row', ['Unit', 'Integration', 'System', 'Acceptance']], ['tbl', [['Level', 'Tests', 'By', 'Technique'], ['Unit', 'One function or module', 'Developer', 'White box, drivers'], ['Integration', 'Interfaces between modules', 'Developer / tester', 'Stubs, drivers'], ['System', 'Whole product vs SRS', 'Test team', 'Black box'], ['Acceptance', 'Business needs', 'Customer', 'Alpha, beta']]]],
  ['## Levels', 'Unit: smallest part, module by module', 'Integration: combine modules, find interface bugs', 'System: complete software, functional and non functional', 'Acceptance: customer decides to accept or reject', '! Alpha = at developer site, Beta = at customer site'], None, False, False),
 S('Integration testing ke chaar tareeke. Big bang: sab modules ek saath jod do, bug dhoondhna mushkil. Top down: upar se neeche jao, neeche ke modules ki jagah stubs lagao, stub matlab nakli callee. Bottom up: neeche se upar jao, upar ke modules ki jagah drivers lagao, driver matlab nakli caller. Sandwich ya hybrid: dono ek saath. Yaad rakho: stub neeche wala, driver upar wala.',
  'Top down = STUBS, Bottom up = DRIVERS, Sandwich = dono',
  [['graph', [('m', 'Main', 0.5, 0.08, 'box', 0), ('a', 'Module A', 0.25, 0.5, 'box', 1), ('b', 'Module B', 0.75, 0.5, 'box', 2), ('c', 'Module C', 0.25, 0.92, 'box', 3), ('d', 'Module D', 0.75, 0.92, 'box', 4)], [('m', 'a'), ('m', 'b'), ('a', 'c'), ('b', 'd')], 250], ['t', 'Top down: Main > A, B > C, D (use stubs).  Bottom up: C, D > A, B > Main (use drivers).']],
  ['## Approaches', 'Big bang: all modules together, hard to locate bugs', 'Top down: test top first, stubs replace lower modules', 'Bottom up: test lowest first, drivers call the modules', 'Sandwich: top down + bottom up meet in the middle', '## PYQ link: scheduling and integration testing', 'Module delivery order decides integration order', 'Late module means more stubs, delay in testing', '! Critical path modules must be integrated and tested first'], None, False, False),
 S('System testing ke andar kai type aate hain. Recovery testing: crash karao, dekho wapas aata hai ya nahi. Security testing: hacker ban kar try karo. Stress testing: limit se zyada load do. Performance testing: speed check. Usability: use karna aasaan hai ya nahi. Aur regression testing: naya change kiya to purana kaam toh nahi bigda. Acceptance mein alpha developer ke paas, beta customer ke paas.',
  'System testing = recovery, security, stress, performance, usability + regression',
  [['h', 'System testing types'], ['tbl', [['Type', 'Checks'], ['Recovery', 'Comes back after crash'], ['Security', 'Unauthorised access blocked'], ['Stress', 'Beyond normal load'], ['Performance', 'Speed, response time'], ['Usability', 'Easy to use'], ['Regression', 'Old features still work']]]],
  ['## Alpha vs Beta', 'Alpha: controlled, at developer site, by internal users', 'Beta: real environment, at customer site, real users', '! Regression test after EVERY change'], None, False, True),
 S('Ab white box testing. Isme code ke andar dekhte hain, isliye ise structural testing bhi bolte hain. Static testing matlab code chalaye bina review karna. Coverage ke chaar type. Statement coverage: har line kam se kam ek baar chale. Branch ya decision coverage: har if ke true aur false dono. Condition coverage: har chhoti condition true aur false. Path coverage: har possible raasta. Path coverage sabse strong hai.',
  'White box = code ke andar. Statement < Branch < Condition < Path',
  [['graph', [('s', 'Start', 0.5, 0.07, 'oval', 5), ('c', 'a > 0 ?', 0.5, 0.4, 'dia', 2), ('t', 'x = 1', 0.2, 0.75, 'box', 1), ('f', 'x = 2', 0.8, 0.75, 'box', 4), ('e', 'End', 0.5, 0.95, 'oval', 5)], [('s', 'c'), ('c', 't', 'True'), ('c', 'f', 'False'), ('t', 'e'), ('f', 'e')], 280]],
  ['## Coverage types', 'Statement: every line runs at least once', 'Branch: every decision true and false', 'Condition: every atomic condition true and false', 'Path: every independent route', '## Example', 'Tests: a=5 (true) and a=-5 (false)', '! 2 tests give 100% statement and branch coverage', '~ Static testing = review without running'], None, False, False),
 S('Basis path testing. Isme pehle control flow graph banate hain. Sequence ek node, if ek decision node, while loop mein wapas edge. Steps: ek, flow graph banao. Do, cyclomatic complexity nikalo. Teen, independent paths likho. Chaar, har path ke liye test case banao. Cyclomatic complexity ke teen formula: E minus N plus 2, ya predicate nodes plus 1, ya regions ki ginti.',
  'Flow graph > V(G) > Independent paths > Test cases',
  [['col', ['1. Draw flow graph from code', '2. Compute V(G)', '3. List independent paths', '4. One test case per path']], ['tbl', [['Formula', 'Meaning'], ['E - N + 2', 'Edges, Nodes'], ['P + 1', 'Predicate (decision) nodes'], ['Regions', 'Closed areas + outside']]]],
  ['## Cyclomatic complexity V(G)', 'V(G) = E - N + 2', 'V(G) = P + 1', 'V(G) = number of regions', '! V(G) = number of independent paths = minimum tests', '~ Higher V(G) means more complex, riskier code'], None, False, False),
 S('Numerical ek. Code: read n, while n bada zero, if n even to even plus plus, else odd plus plus, n minus minus, aakhir mein print. Nodes saat hain, ek se saat. Edges: ek do, do teen, do saat, teen chaar, teen paanch, chaar chhe, paanch chhe, chhe do. Total aath edges. V G barabar aath minus saat plus do barabar teen. Predicate nodes do hain, to P plus ek bhi teen. Teen independent paths: ek do saat, ek do teen chaar chhe do saat, aur ek do teen paanch chhe do saat.',
  'E = 8, N = 7 => V(G) = 3 independent paths',
  [['graph', [('1', '1 read n', 0.5, 0.05, 'circ', 0), ('2', '2 n > 0', 0.5, 0.27, 'dia', 2), ('3', '3 even?', 0.3, 0.52, 'dia', 2), ('4', '4', 0.12, 0.78, 'circ', 1), ('5', '5', 0.48, 0.78, 'circ', 4), ('6', '6 n--', 0.3, 0.97, 'circ', 3), ('7', '7 print', 0.85, 0.5, 'circ', 5)], [('1', '2'), ('2', '3', 'yes'), ('2', '7', 'no'), ('3', '4'), ('3', '5'), ('4', '6'), ('5', '6'), ('6', '2')], 330]],
  ['## Count', 'Nodes N = 7', 'Edges E = 8', 'V(G) = E - N + 2 = 8 - 7 + 2 = 3', 'Predicates: node 2, node 3 so P = 2', 'V(G) = P + 1 = 3', '## Independent paths', 'P1: 1-2-7', 'P2: 1-2-3-4-6-2-7', 'P3: 1-2-3-5-6-2-7', '## Test cases', 'n = 0 covers P1, n = 2 covers P2, n = 1 covers P3', '! V(G) = 3, three test cases'], None, False, False),
 S('Numerical do: lab wala quadratic roots program. Input a b c, 1 se 100. Output: imaginary, real, equal ya not a quadratic. Flow: agar a zero to not quadratic. Warna d barabar b square minus four a c. Agar d negative to imaginary, d zero to equal, warna real. Nodes das, edges barah. V G barabar barah minus das plus do barabar chaar. Predicates teen to teen plus ek chaar. Chaar test cases: a zero b paanch c paanch, a ek b ek c ek, a ek b do c ek, a ek b paanch c ek.',
  'Quadratic roots: E = 12, N = 10 => V(G) = 4 => 4 test cases',
  [['graph', [('1', '1 input', 0.5, 0.04, 'circ', 0), ('2', '2 a = 0?', 0.5, 0.2, 'dia', 2), ('3', '3 Not quad', 0.1, 0.42, 'box', 4), ('4', '4 d = b2 - 4ac', 0.62, 0.38, 'box', 1), ('5', '5 d < 0?', 0.62, 0.58, 'dia', 2), ('6', '6 Imaginary', 0.15, 0.78, 'box', 3), ('7', '7 d = 0?', 0.62, 0.78, 'dia', 2), ('8', '8 Equal', 0.4, 0.97, 'box', 3), ('9', '9 Real', 0.88, 0.97, 'box', 3), ('10', '10 End', 0.1, 0.97, 'circ', 5)], [('1', '2'), ('2', '3', 'yes'), ('2', '4', 'no'), ('4', '5'), ('5', '6', 'yes'), ('5', '7', 'no'), ('7', '8', 'yes'), ('7', '9', 'no')], 340]],
  ['## V(G)', 'N = 10, E = 12', 'V(G) = 12 - 10 + 2 = 4', 'P = 3 (a=0, d<0, d=0) so P + 1 = 4', '## Independent paths', 'P1: 1-2-3-10', 'P2: 1-2-4-5-6-10', 'P3: 1-2-4-5-7-8-10', 'P4: 1-2-4-5-7-9-10', '## Test cases (a,b,c)', '(0,5,5) Not quadratic', '(1,1,1) d=-3 Imaginary', '(1,2,1) d=0 Equal', '(1,5,1) d=21 Real', '! 4 test cases'], None, False, True),
 S('Black box testing ab. Code nahi dekhte, sirf input aur output. Boundary value analysis: bug aksar boundary par hote hain. Har variable ke liye paanch values: minimum, minimum plus ek, nominal, maximum minus ek, maximum. Ek variable badalte hain, baaki nominal. Agar n variables hain to normal BVA mein four n plus one cases. Robust mein minimum se ek kam aur maximum se ek zyada bhi, to six n plus one. Worst case mein sab combinations, paanch ki power n. Quadratic mein teen variables, range ek se sau, nominal pachaas. Normal BVA ke terah cases. Robust ke unnis.',
  'BVA: min, min+, nom, max-, max.  4n+1, robust 6n+1, worst 5^n',
  [['tbl', [['Type', 'Cases', 'n = 3'], ['Normal BVA', '4n + 1', '13'], ['Robust BVA', '6n + 1', '19'], ['Worst case', '5^n', '125'], ['Robust worst', '7^n', '343']]], ['t', 'Range 1..100, nominal 50. Robust adds 0 and 101.']],
  ['## BVA a,b,c in [1,100], nom 50', '(1,50,50) Real  (2,50,50) Real', '(99,50,50) Imag  (100,50,50) Imag', '(50,1,50) Imag  (50,2,50) Imag', '(50,99,50) Imag  (50,100,50) Equal', '(50,50,1) Real  (50,50,2) Real', '(50,50,99) Imag  (50,50,100) Imag', '(50,50,50) Imag (nominal)', '! 4n + 1 = 13 cases', '## Robust adds', '0 and 101 for each variable: 6 more = 19 cases', '~ Outputs: d = b2 - 4ac'], None, False, False),
 S('Equivalence class testing. Input domain ko classes mein baanto, har class se ek test case lo, kyunki class ke andar sab values same behave karti hain. Example: age 18 se 60 valid. To teen classes: valid 18 se 60, invalid 18 se kam, invalid 60 se zyada. Test values 30, 10, 70. Weak normal mein ek time par ek class, strong mein sab classes ke combinations. Robust mein invalid classes bhi.',
  'Domain ko classes mein todo, har class se ek test',
  [['h', 'Age must be 18 to 60'], ['row', ['Invalid: < 18', 'Valid: 18 to 60', 'Invalid: > 60']], ['tbl', [['Class', 'Test value', 'Expected'], ['< 18', '10', 'Reject'], ['18 - 60', '30', 'Accept'], ['> 60', '70', 'Reject']]]],
  ['## ECP steps', '1. Find input conditions', '2. Divide into valid and invalid classes', '3. Pick one value from each class', '! 3 classes = 3 test cases', '## Types', 'Weak normal: one class at a time', 'Strong normal: all combinations of valid classes', 'Robust: also invalid classes'], None, False, False),
 S('Ab PYQ chaar c wala, credit card discount. Conditions: new customer paindrah percent. Existing customer jiske paas loyalty card hai, das percent. Coupon ho to bees percent, lekin new customer ke saath nahi chalega. Discount add hote hain. Pehle decision table banao. Conditions teen: new, loyalty, coupon. Rule ek: new haan, baaki nahi, paindrah. Rule do: new aur coupon, coupon block, phir bhi paindrah. Rule teen: existing aur loyalty, das. Rule chaar: existing, loyalty, coupon, tees. Rule paanch: existing aur sirf coupon, bees. Rule chhe: kuch nahi, zero. Code mein teen if hain, to V G barabar chaar. Branch coverage ke liye teen tests kaafi, lekin condition coverage ke liye chhe test.',
  'Decision table: har column ek rule = ek test case',
  [['tbl', [['Rule', 'New', 'Loyal', 'Coupon', 'Disc'], ['R1', 'Y', 'N', 'N', '15%'], ['R2', 'Y', 'N', 'Y', '15%'], ['R3', 'N', 'Y', 'N', '10%'], ['R4', 'N', 'Y', 'Y', '30%'], ['R5', 'N', 'N', 'Y', '20%'], ['R6', 'N', 'N', 'N', '0%']]], ['t', 'New and Loyal together is impossible (assumption).']],
  ['## Code (white box)', '2 if new: d += 15', '3 if not new and loyal: d += 10', '4 if not new and coupon: d += 20', 'V(G) = 3 decisions + 1 = 4', '## Branch coverage (3 tests)', 'T1 new=Y: 15', 'T2 new=N, loyal=Y, coupon=Y: 30', 'T3 all N: 0', '## Condition coverage adds', 'T4 new=Y, coupon=Y: 15 (blocked)', 'T5 loyal only: 10', 'T6 coupon only: 20', '! 6 tests cover all rules'], None, False, True),
 S('Cause effect graph aur state table. Cause effect mein causes matlab input conditions ko effects matlab outputs se logic gates AND, OR, NOT se jodte hain, phir usse decision table banti hai. Jaise new customer cause ek, coupon cause do, discount paindrah effect. State table testing mein rows states hain, columns events, aur cell mein agla state. ATM example: idle state mein card dalo to PIN wait state, galat PIN teen baar to blocked. Har state event pair ke liye ek test case.',
  'Cause effect > decision table. State table: har state x event ek test',
  [['tbl', [['State', 'Card', 'Right PIN', 'Wrong PIN'], ['Idle', 'Wait PIN', '-', '-'], ['Wait PIN', '-', 'Menu', 'Retry / Block'], ['Menu', '-', 'Transaction', '-']]], ['graph', [('i', 'Idle', 0.1, 0.5, 'oval', 5), ('w', 'Wait PIN', 0.4, 0.5, 'oval', 0), ('m', 'Menu', 0.7, 0.2, 'oval', 3), ('b', 'Blocked', 0.7, 0.85, 'oval', 4)], [('i', 'w', 'card'), ('w', 'm', 'ok'), ('w', 'b', '3 wrong')], 150]],
  ['## Cause effect graph steps', '1. List causes (inputs) and effects (outputs)', '2. Draw graph with AND, OR, NOT', '3. Convert to decision table', '4. Each column = test case', '## State table testing', 'Rows = states, columns = events, cell = next state', '! Test every state and event pair'], None, False, False),
 S('Last topic, agile testing aur TDD. Agile mein testing alag phase nahi, har sprint mein chalti hai, tester developer saath kaam karte hain. TDD matlab Test Driven Development. Pehle test likho, wo fail hoga, yeh Red. Phir minimum code likho jo pass kare, yeh Green. Phir code saaf karo, yeh Refactor. Phir repeat. Agile testing quadrants: unit tests, functional tests, exploratory tests aur performance security tests.',
  'TDD: Red (fail) > Green (pass) > Refactor > repeat',
  [['graph', [('r', 'RED: write failing test', 0.5, 0.08, 'box', 4), ('g', 'GREEN: write code to pass', 0.9, 0.55, 'box', 1), ('f', 'REFACTOR: clean code', 0.1, 0.9, 'box', 2)], [('r', 'g'), ('g', 'f'), ('f', 'r')], 250], ['tbl', [['Quadrant', 'Tests'], ['Q1', 'Unit, component (tech, supports team)'], ['Q2', 'Functional, story tests'], ['Q3', 'Exploratory, UAT'], ['Q4', 'Performance, security']]]],
  ['## Agile testing', 'Testing done continuously inside every sprint', 'Tester and developer work together', 'Automated regression suite after every build', '## TDD', 'Write test first, it fails (Red)', 'Write minimum code to pass (Green)', 'Improve design without changing behaviour (Refactor)', '! Benefit: fewer bugs, safe changes, living documentation'], None, False, False),
])
